function toPosix(value) { return path.resolve(value).split(path.sep).join("/"); }
function readBytes(filePath) { return fs.readFileSync(filePath); }
function readJson(filePath) { return JSON.parse(readBytes(filePath).toString("utf8")); }
function sha256Bytes(bytes) { return crypto.createHash("sha256").update(bytes).digest("hex").toUpperCase(); }
function binding(filePath) { const bytes = readBytes(filePath); return { absolute_path: toPosix(filePath), sha256: sha256Bytes(bytes), bytes: bytes.length }; }
function failClosed(condition, code, detail) { if (!condition) { const error = new Error(`${code}: ${detail}`); error.code = code; throw error; } }
function writeJson(relativePath, value) { const target = path.join(TASK_ROOT, relativePath); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`, "utf8"); }
function writeText(relativePath, value) { const target = path.join(TASK_ROOT, relativePath); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, value.endsWith("\n") ? value : `${value}\n`, "utf8"); }
function listFiles(root) { const result = []; function visit(current) { for (const entry of fs.readdirSync(current, { withFileTypes: true })) { const target = path.join(current, entry.name); if (entry.isDirectory()) visit(target); else if (entry.isFile()) result.push(target); } } visit(root); return result; }
function treeDigest(root) { const rows = listFiles(root).map((filePath) => ({ relative_path: path.relative(root, filePath).split(path.sep).join("/"), sha256: sha256Bytes(readBytes(filePath)), bytes: fs.statSync(filePath).size })).sort((a, b) => a.relative_path < b.relative_path ? -1 : a.relative_path > b.relative_path ? 1 : 0); const canonical = rows.map((row) => `${row.relative_path}|${row.sha256}|${row.bytes}`).join("\n"); return { file_count: rows.length, manifest_sha256: sha256Bytes(Buffer.from(canonical, "utf8")) }; }
function fileNames(root) { return fs.readdirSync(root, { withFileTypes: true }).filter((entry) => entry.isFile()).map((entry) => entry.name).sort(); }
function slug(name) { return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }
function categoryDir(category) { return category.toLowerCase().replaceAll("_objects", "").replaceAll("_", "-"); }
function proposalState(extra = {}) { return { core_object_library_status: STATUS.library, normative_object_library: STATUS.normative, human_adoption_required: STATUS.humanAdoptionRequired, ...extra }; }

